public class Main {
    static long fact(int n) {
        if (n == 1) {
            return 1;
        }
        return n * fact(n - 1);
    }

    public static void main(String[] args) {
        System.out.println("1! = " + fact(1));
        System.out.println("0! = " + fact(0));
    }
}

